const main = document.querySelector('main');
const escapeText = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
const cartIcon = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M2 4h3l3 12h11l2-9H6"/><circle cx="9" cy="20" r="1"/><circle cx="18" cy="20" r="1"/></svg>';
const dedication = "<div class=\"dedication\"><span>I&#39;m fine in the dark.</span> <span>Just not without you.</span></div>";
const $ = id => document.getElementById(id);
let displayOrder;
let data, products, bag = JSON.parse(localStorage.getItem('mine-bag-v2') || '{}');
const notes=JSON.parse(localStorage.getItem('meowfield-notes')||'{}');
const entries = () => Object.entries(bag).filter(([id,n]) => products.has(id) && Number.isInteger(n) && n>0);
const cartSyncKey = 'meowfield-cart-sync';
let cartSyncQueue = Promise.resolve();

function cartSharingEnabled() {
 const state = localStorage.getItem(cartSyncKey);
 return state !== 'off' && (Boolean(state) || !localStorage.getItem('meowfield-cart-id'));
}
function sharingNotice() {
 return cartSharingEnabled() ? '加购后，商品、数量和备注会自动同步给 mcw，按日保存。' : '购物车自动同步已关闭。';
}
function syncCartRecord() {
 if (!cartSharingEnabled()) return;
 let key = localStorage.getItem(cartSyncKey);
 if (!key) {
  key = crypto.randomUUID();
  localStorage.setItem(cartSyncKey,key);
  localStorage.setItem('meowfield-cart-id',key);
 }
 const body = JSON.stringify({key, lines:entries().map(([id,qty])=>[id,qty,notes[id]||''])});
 const send = async () => {
  if (localStorage.getItem(cartSyncKey) !== key) return;
  const result = await fetch('/api/cart-records', {
   method:'POST',headers:{'Content-Type':'application/json'},body,
   keepalive:new Blob([body]).size < 60000,
  });
  if (!result.ok) throw Error('Cart sync failed');
 };
 cartSyncQueue = cartSyncQueue.then(send).catch(()=>notice('购物车同步失败，本机选款已保留'));
}

function sync({record=true}={}){
 localStorage.setItem('mine-bag-v2', JSON.stringify(bag));
 $('count').textContent=entries().reduce((s,[,n])=>s+n,0);
 if(record)syncCartRecord();
}
function money(y,rate=data.rate){
 return '<strong>JP¥ '+y.toLocaleString('en-US')+'</strong> <span>约 CN¥ '+(y*rate).toFixed(2)+'</span>';
}
function notice(msg){$('toast').textContent=msg;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('toast').textContent='',1900);}
function opening(){
 if(location.pathname!=='/' || (sessionStorage.mineIntro && !new URLSearchParams(location.search).has('intro')) || matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 sessionStorage.mineIntro='1';const el=document.createElement('div');el.className='intro';
 el.innerHTML='<div class="flight"><svg viewBox="0 0 160 72"><path fill="currentColor" d="M80 27l-8-11-1 10C50 17 29 9 3 4q17 14 16 35 12-10 23 5 12-8 20 6 10-3 18 17 7-20 18-17 9-14 20-6 11-15 23-5-1-21 16-35-34 7-68 22l-1-10z"/></svg></div><div class="signature"><img class="wordmark" src="/img/meowfield-header.svg" alt="Meowfield">'+dedication+'</div><button>跳过</button>';
 document.body.append(el);el.querySelector('button').onclick=()=>el.remove();setTimeout(()=>el.remove(),4400);
}
opening();
const detail = id => '/product?id='+encodeURIComponent(id);
const addButton = (p,text='') => '<button class="'+(text?'primary':'add')+'" data-add="'+p.id+'" aria-label="加入购物车">'+cartIcon+text+'</button>';
function home(){
 main.innerHTML='<section class="cover moon-cover"><canvas class="meadow" data-source="data:image/jpeg;base64," aria-hidden="true" hidden></canvas><div class="copy"><h1 class="cover-handwriting" aria-label="Mine Street · 买不了全部！"></h1><a class="browse" href="#collection">浏览选款 ↘</a></div></section><section id="collection"><div class="collection-head"><div class="collection-portrait-frame"><img class="collection-portrait" src="/img/misstt.png" data-outfits="/img/misstt-outfits.json" width="219" height="287" alt="misstt"></div><div class="collection-controls"><div class="brand-filter"><button type="button" class="brand-toggle" id="brand-toggle" aria-expanded="false" aria-controls="brand-panel"><span>品牌 · <span id="brand-current">全部品牌</span></span><span class="brand-chevron" aria-hidden="true">⌄</span></button><div class="brand-panel" id="brand-panel" inert aria-hidden="true"><div class="brand-options" id="brand-options"></div></div></div><div class="collection-style"><select id="styles" aria-label="款式"></select></div></div></div><p id="info"></p><div id="grid"></div><button class="primary" id="more">查看更多</button></section>';
 let brand='',limit=24;
 function options(){
 const select = $('styles'), previous = select.value;
 const categories = [...new Set(data.items.filter(p => !brand || p.brand === brand).map(p => collectionCategory(p.type)))];
 select.replaceChildren(new Option('全部款式', ''), ...categories.map(category => new Option(category, category)));
 if (categories.includes(previous)) select.value = previous;
 }
 function draw(){
 const all=displayOrder.filter(p=>(!brand||brand===p.brand)&&(!$('styles').value||$('styles').value===collectionCategory(p.type)));
 $('info').textContent=all.length+' 件 · 汇率日期 '+data.date+' · '+sharingNotice();
 $('grid').innerHTML=all.slice(0,limit).map(p=>'<article><a class="image" href="'+detail(p.id)+'"><img loading="lazy" src="'+escapeText(p.photo)+'" alt="'+escapeText(p.name)+'"></a><small>'+escapeText(p.brand)+'</small><h3><a href="'+detail(p.id)+'">'+escapeText(p.name)+'</a></h3><div class="cost"><div>'+money(p.price)+'</div>'+addButton(p)+'</div></article>').join('');
 $('more').hidden=limit>=all.length;
 }
 setupMissttPortrait();
 setupBrandFilter(new Set(data.items.map(p => p.brand)), selected => {
   brand = selected;
   limit = 24;
   options();
   draw();
 });
 $('styles').onchange=()=>{limit=24;draw()};$('more').onclick=()=>{limit+=48;draw()};options();draw();
 const meadow = document.createElement('script');
 meadow.src='/meadow.js';document.head.append(meadow);
 if(location.hash==='#collection')$('collection').scrollIntoView();
}
function description(p){
 const translated = p.descriptionZh?.trim();
 const original = p.descriptionJa?.trim();
 const content = translated || original || (p.descriptionStatus === 'confirmed-empty'
   ? '暂无官方简介，但 mcw 一定会觉得你穿这件还不错。'
   : '简介暂未读取，可访问原站查看。');
 return '<div class="product-description"><h3>商品简介</h3>' +
   (!translated && original ? '<small>原店日文</small>' : '') +
   '<p>'+escapeText(content)+'</p></div>';
}
async function product(){
 const p=products.get(new URLSearchParams(location.search).get('id'));if(!p){main.textContent='未找到商品';return;}
 main.innerHTML='<div class="spread"><div class="gallery"><img id="hero" class="heroImg" src="'+escapeText(p.photo)+'" alt="'+escapeText(p.name)+'"><div id="thumbs"></div><p id="galleryState">正在读取原店图片…</p></div><section class="product-info"><small>'+escapeText(p.brand)+'</small><h2>'+escapeText(p.name)+'</h2><p>'+escapeText(collectionCategory(p.type))+'</p><div class="amount">'+money(p.price)+'</div><p>汇率日期 '+data.date+'</p>'+addButton(p,' 加入购物车')+' <a class="browse" target="_blank" rel="noopener" href="'+escapeText(p.url)+'">访问原站 ↗</a>'+description(p)+'</section></div>';
 main.querySelector('[data-add]').insertAdjacentHTML('beforebegin','<p>'+sharingNotice()+'</p>');
 try{const r=await fetch('/api/gallery?id='+p.id);if(!r.ok)throw Error();const urls=await r.json();$('galleryState').textContent=urls.length>1?'共 '+urls.length+' 张图片':'原店仅返回封面图';
 if (urls.length > 1) {
   urls.forEach((url, i) => {
     const button = document.createElement('button'), img = new Image();
     img.src = url; img.alt = '查看第 '+(i+1)+' 张'; img.loading = 'lazy';
     button.type = 'button';
     button.setAttribute('aria-pressed', String(url === $('hero').src));
     button.append(img);
     button.onclick = () => {
       $('hero').src = url;
       for (const peer of $('thumbs').children) peer.setAttribute('aria-pressed', String(peer === button));
     };
     $('thumbs').append(button);
   });
 }}catch{$('galleryState').textContent='原店图片暂未载入，可刷新重试。';}
}
function line(p,n,rate,edit){
 return '<div class="line'+(edit?' cart-line':'')+'"><a href="'+detail(p.id)+'"><img src="'+escapeText(p.photo)+'" alt="'+escapeText(p.name)+'"></a><div><small>'+escapeText(p.brand)+'</small><h3>'+escapeText(p.name)+'</h3>'+money(p.price*n,rate)+'</div><div'+(edit?' class="cart-actions"':'')+'><span>× '+n+'</span>'+(edit?'<button data-note="'+p.id+'">'+(notes[p.id]?'编辑备注':'写备注')+'</button><button data-remove="'+p.id+'">移除</button>':'')+'</div>'+((edit?notes[p.id]:p.note)?'<p class="item-note">'+escapeText(edit?notes[p.id]:p.note)+'</p>':'')+'</div>';
}
function cart(){
 const list=entries();
 main.innerHTML='<section class="sheet cart-shell"><small>YOUR SELECTION</small><h2>购物车</h2>'+list.map(([id,n])=>line(products.get(id),n,data.rate,true)).join('')+(list.length?'<footer class="cart-total"><div>合计 '+money(list.reduce((s,[id,n])=>s+products.get(id).price*n,0))+'</div><button class="primary" id="submit">提交给 mcw</button></footer>':'<div class="cart-empty"><p>购物车还是空的。</p><a href="/#collection">继续选款 →</a></div>')+'</section>';
 const enabled = cartSharingEnabled();
 main.querySelector('.cart-shell').insertAdjacentHTML('beforeend',
  '<p>'+sharingNotice()+'</p>'+
  '<button type="button" id="cart-sync" aria-pressed="'+enabled+'">'+(enabled?'停止同步购物车':'开启购物车同步')+'</button>');
 $('cart-sync').onclick=()=>{
  if(enabled)localStorage.setItem(cartSyncKey,'off');
  else {
   let cartId=localStorage.getItem('meowfield-cart-id');
   if(!cartId){cartId=crypto.randomUUID();localStorage.setItem('meowfield-cart-id',cartId);}
   localStorage.setItem(cartSyncKey,cartId);
   syncCartRecord();
  }
  cart();
 };
 if($('submit'))$('submit').onclick=async()=>{const btn=$('submit');main.inert=true;btn.disabled=true;try{
 const key=localStorage.getItem('mine-request')||crypto.randomUUID();localStorage.setItem('mine-request',key);
 const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,lines:list.map(([id,n])=>[id,n,notes[id]||''])})});if(!r.ok)throw Error();
 for(const [id] of list)delete notes[id];saveNotes();bag={};sync();localStorage.removeItem('mine-request');cart();$('success').showModal();
 }catch{btn.disabled=false;notice('提交失败，购物车已保留');}finally{main.inert=false;}};
}
async function admin(){
 const responses=await Promise.all([fetch('/api/cart-records'),fetch('/api/orders')]);
 if(responses.some(response=>!response.ok))throw Error();
 const [carts,orders]=await Promise.all(responses.map(response=>response.json()));
 main.innerHTML='<section class="sheet"><h2>选款管理</h2><p><button id="refresh">刷新</button></p>'+
  '<h3>购物车记录 · '+carts.length+' 份</h3>'+(renderArchive(carts,true)||'<p>暂无购物车记录。</p>')+
  '<h3>已提交选款 · '+orders.length+' 份</h3>'+(renderArchive(orders,false)||'<p>暂无提交。</p>')+'</section>';
 $('refresh').onclick=()=>admin().catch(()=>notice('刷新失败，请重试'));
 for(const button of main.querySelectorAll('[data-delete-record]')){
  button.onclick=async()=>{
   const {deleteRecord:key,recordDay:day}=button.dataset;
   if(!confirm('删除这份'+(day?'购物车归档':'已提交选款')+'？'))return;
   button.disabled=true;
   const query=new URLSearchParams({key});
   if(day)query.set('day',day);
   try{
    const response=await fetch((day?'/api/cart-records':'/api/orders')+'?'+query,{method:'DELETE'});
    if(!response.ok)throw Error('Delete failed');
   }catch{
    button.disabled=false;
    notice('删除失败，请重试');
    return;
   }
   button.closest('.order').remove();
   await admin().catch(()=>notice('记录已删除，列表刷新失败'));
  };
 }
}
function renderArchive(orders,isCart){
 const timeZone='Asia/Shanghai';
 const dateFormat=new Intl.DateTimeFormat('zh-CN',{timeZone,year:'numeric',month:'long',day:'numeric'});
 const timeFormat=new Intl.DateTimeFormat('zh-CN',{timeZone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
 const days=new Map();
 for(const order of [...orders].sort((a,b)=>Date.parse(b.created)-Date.parse(a.created))){
  const day=dateFormat.format(new Date(order.created));
  if(!days.has(day))days.set(day,[]);
  days.get(day).push(order);
 }
 return [...days].map(([day,records],index)=>'<details class="archive" '+(index===0?'open':'')+'><summary>'+day+' · '+records.length+' 份</summary>'+records.map(o=>
  '<article class="order"><small>'+timeFormat.format(new Date(o.created))+(isCart?' · 购物车 '+escapeText(o.key.slice(0,8)):'')+'</small>'+
  '<h3>'+(isCart?'购物车':'选款清单')+' · '+o.lines.reduce((s,p)=>s+p.qty,0)+' 件</h3>'+
  o.lines.map(p=>line(p,p.qty,o.rate,false)).join('')+
  '<footer class="cart-total"><span>记录时合计 '+money(o.lines.reduce((s,p)=>s+p.price*p.qty,0),o.rate)+'</span>'+
  '<button type="button" data-delete-record="'+escapeText(o.key)+'"'+(isCart?' data-record-day="'+escapeText(o.day)+'"':'')+'>删除记录</button></footer></article>'
 ).join('')+'</details>').join('');
}
function saveNotes(){localStorage.setItem('meowfield-notes',JSON.stringify(notes));}
function editNote(id){
 const dialog=document.createElement('dialog');
 dialog.innerHTML='<form class="note-form"><label>商品备注<textarea maxlength="500" rows="5" placeholder="写下你对这件的想法"></textarea></label><div><button type="button">取消</button><button class="primary">保存备注</button></div></form>';
 const input=dialog.querySelector('textarea');input.value=notes[id]||'';
 dialog.querySelector('[type=button]').onclick=()=>dialog.close();
 dialog.querySelector('form').onsubmit=e=>{
  e.preventDefault();const note=input.value.trim();
  if(note)notes[id]=note;else delete notes[id];
 saveNotes();localStorage.removeItem('mine-request');syncCartRecord();dialog.close();cart();
  main.querySelector('[data-note="'+id+'"]')?.focus();
 };
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 document.body.append(dialog);dialog.showModal();input.focus();
}
main.addEventListener('click',e=>{const a=e.target.closest('[data-add]'),r=e.target.closest('[data-remove]');if(a){const id=a.dataset.add;bag[id]=Math.min((bag[id]||0)+1,999);sync();localStorage.removeItem('mine-request');notice('已加入购物车');}const noteButton=e.target.closest('[data-note]');if(noteButton)editNote(noteButton.dataset.note);if(r){delete notes[r.dataset.remove];saveNotes();delete bag[r.dataset.remove];sync();localStorage.removeItem('mine-request');cart();}});
(async()=>{data=await(await fetch('/catalog.json')).json();products=new Map(data.items.map(p=>[p.id,p]));
 const groups=[...new Set(data.items.map(p=>p.brand))].map(b=>data.items.filter(p=>p.brand===b));
 displayOrder=[];for(let i=0;i<Math.max(...groups.map(g=>g.length));i++)for(const group of groups)if(group[i])displayOrder.push(group[i]);
 const legacyPage=new URLSearchParams(location.search).get('page');
 sync({record:false});if((location.pathname==='/cart'||legacyPage==='cart'))cart();else if((location.pathname==='/product'||legacyPage==='product'))await product();else if(location.pathname.startsWith('/admin'))await admin();else home();})().catch(()=>main.textContent='页面读取失败，请刷新重试。');
